Game::~Game() {
    if (minimapTexture_ && minimapRenderer_)
        minimapRenderer_->destroyTexture(
            minimapTexture_);
    if (fogTexture_ && fogRenderer_)
        fogRenderer_->destroyTexture(
            fogTexture_);
}

