    if (!object) return ids;
    for (ActionMenuTab category :
         {ActionMenuTab::Economy,
          ActionMenuTab::Military,
          ActionMenuTab::Defense})
        for (const dat::Unit *unit :
             buildingOptions(*object, category))
            ids.push_back(unit->id);
    return ids;
